#!/usr/bin/env python3
"""Generates data/knights/paracelsa.json (Knightbook 'A Knight's Tale: Paracelsa' p.3-4, Portrait / Talent / Heroic Arc / Technique sheets, owner-supplied 2026-11-16).
Arc icons read with the 'Knight Tokens and Abilities' legend; the saw icon is the Zeal token."""
import json, os
T = lambda token, n=1: {"token": token, "n": n}
H = lambda n: {"res": "Heat", "n": n}
Z = lambda n: {"res": "Zeal", "n": -n}
V = lambda n: {"res": "Vigor", "n": -n}
ACT = lambda *a: {"res": "Action", "actions": list(a)}
PR = T("PowerReroll", 1); RED = T("PowerDieRed", 1)
def ex(tok, dep): return {"token": tok, "n": 1, "depletion": dep}
def arc(name, plus, levels, unclear=()): return {"name": name, "plus": plus, "levels": [{"level": i + 1, "options": o} for i, o in enumerate(levels)], "unclear": list(unclear)}
FAL = {"text": "Falsity", "ops": [T("Falsity")]}
arcs = [
 arc("Quester", None, [[[T("Break")], [T("Opening")]], [[PR]], [[T("Break"), T("Reposition")]], [[T("Break")], [T("Opening")], [T("Zeal")]], [[RED, T("Hug"), T("Break")]], [[T("Zeal"), T("Rouse")]]]),
 arc("Faithful", None, [[[T("Overbreak"), T("Opening")]], [[PR, T("Fire")]], [[T("Fire"), T("Reposition")]], [[T("Break")], [T("Opening")], [T("Zeal")]], [[RED, T("Opening"), T("Hug")]], [[T("Rouse"), T("Fire")]], [[PR]]]),
 arc("Truthseeker", FAL, [[[T("Fire"), T("Opening")]], [[PR, T("Fire")]], [[T("Opening"), T("Zeal")]], [[RED, T("Reposition"), T("Opening")]], [[PR, T("Fire"), T("Zeal")]], [[T("Hope"), T("Reposition")]], [[T("Deadly"), T("Fire")]]]),
 arc("Fireheart Zealot", None, [[[T("Black"), T("Opening")]], [[PR, T("Opening")]], [[T("Black"), T("Zeal")]], [[RED, T("Reposition")]], [[PR, T("Hope")]], [[T("Zeal"), T("GreaterPass"), T("Black")]], [[T("Spotlight"), T("Break")]]]),
 arc("Questioner", FAL, [[[T("Fire", 2)]], [[T("Reposition"), T("Opening")]], [[T("Closing"), T("Pass")]], [[RED, T("Zeal")]], [[T("Zeal"), T("Fire", 2), T("Reposition")]], [[PR, T("Hope")]], [[T("Deadly"), T("GreaterPass")]]]),
 arc("Inquisitor", {"text": "Auto-fire 1", "ops": [T("AutoFire")]}, [[[T("Fire"), T("Opening")]], [[PR, T("Reposition")], [T("Hope"), T("Zeal")]], [[T("Closing"), T("Fire", 2)], [T("Opening", 2), T("Black")]], [[RED, T("Fire"), T("Zeal")]], [[PR], [T("Tireless"), T("Reposition")]], [[T("Hope"), T("GreaterPass")]], [[T("Deadly"), T("Break")]], [[T("Provoke")]]]),
 arc("Apostate", FAL, [[[T("Black"), T("Opening")]], [[T("Break", 2), T("Zeal")]], [[PR, T("Closing"), T("Break")]], [[RED, T("Zeal"), T("Black")]], [[T("Black"), T("Pass")]], [[T("Zeal"), PR]], [[T("Spotlight"), T("GreaterPass")]], [[T("Hope")]]]),
 arc("Reverent", {"text": "Falsity, +1 [Power]", "ops": [T("Falsity"), T("PlusPower")]}, [[[T("Fire", 2), T("Zeal"), PR]], [[T("Hope"), T("Closing"), T("Reposition", 2)]], [[T("Closing"), T("Zeal"), PR]], [[RED, T("Hope")]], [[T("Sunder"), T("Zeal")]], [[T("Daze")], [T("Provoke")]], [[T("Hope", 2), PR]], [[T("Power")]]]),
]
B = lambda at, kind, n=1: {"at": at, "kind": kind, "n": n}
DIE = "When you are about to die, if you have {n}+ Zeal [Zeal] tokens, immediately stand up, move up to 3 spaces and perform a Bonus Attack!"
talents = [
 {"id": "quester", "name": "Quester", "tier": "starting", "abilities": [
   {"name": "Unwavering Faith", "text": "Crit Miss: Zeal 1. When you resolve a [Judicium draw] or another Knight draws a Judicium, Zeal 1. You gain the following stacking benefits depending on the number of Zeal [Zeal] tokens on your Knight Board: 1: Evasion Re-roll 1. 2: Attack Re-roll 1. 3: [Power Re-roll] 1. Zeal Threshold: 3.",
    "ops": [{"op": "zeal", "critMiss": 1, "onJudicium": 1, "threshold": 3, "benefits": [B(1, "evasionReroll"), B(2, "attackReroll"), B(3, "powerReroll")]}]},
   {"name": "Martyr's Zeal", "text": DIE.format(n=3) + " (You still die afterwards.)", "ops": [{"op": "dieStand", "need": 3, "survive": False}]}]},
 {"id": "truthseeker", "name": "Truthseeker", "tier": "vassal", "abilities": [
   {"name": "Dedicated Disciple", "text": "Start of your turn: Zeal 2. As long as you have 3+ Zeal [Zeal] tokens on your Knight Board, gain Auto-hope 1. When you deal a Wound, if you have 6+ Zeal [Zeal] tokens, [Discard] this Talent card (you lose it until the end of Clash), immediately Reposition 3 and perform a Bonus Attack!",
    "ops": [{"op": "turnZeal", "n": 2}, {"op": "zealAutoHope", "need": 3, "n": 1}, {"op": "woundDiscardBonus", "need": 6}]},
   {"name": "Undying Devotion", "text": DIE.format(n=3) + " If you deal a Wound, you survive and [Discard] this Talent card (you lose it until the end of Clash). Otherwise, you die.", "ops": [{"op": "dieStand", "need": 3, "survive": True, "discardTalent": True}]}]},
 {"id": "fireheart-zealot", "name": "Fireheart Zealot", "tier": "vassal", "abilities": [
   {"name": "Fervent Acolyte", "text": "One or more Misses: Zeal 1. When you resolve a [Judicium draw] or another Knight draws a Judicium, Zeal 1. You gain the following stacking benefits depending on the number of Zeal [Zeal] tokens on your Knight Board: 1: Auto-break 1. 2: +1 [Speed]. 3: Attack Re-roll 1. 4: [icon]. 5: Sacrifice. 6: [icon]. 7: [icon]. Zeal Threshold: 7.",
    "ops": [{"op": "zeal", "onMiss": 1, "onJudicium": 1, "threshold": 7, "benefits": [B(1, "autoBreak"), B(2, "speed"), B(3, "attackReroll"), B(5, "sacrifice")]}], "unclear": ["Benefits 4, 6 and 7 are single icons that cannot be read at the sheet's resolution — not applied"]},
   {"name": "Preacher's Pyre", "text": "When you spend Zeal [Zeal] tokens from your Knight Board, place a Fire [Fire] token in the Knight Pool.", "ops": [{"op": "preachersPyre"}]}]},
 {"id": "inquisitor", "name": "Inquisitor", "tier": "devil", "abilities": [
   {"name": "Consecrated Champion", "text": "One or more Misses: Zeal 2. When you resolve a [Judicium draw] or another Knight draws a Judicium, Zeal 2. You gain the following stacking benefits depending on the number of Zeal [Zeal] tokens on your Knight Board: 1: +1 [Power]. 2: Evasion Re-roll 1. 3: Tumble. 4: +1 [Speed]. 5: +1 [Precision]. 6: Attack Re-roll 1. 7: Auto-break 1. 8: Deadly. 9: -1 [icon]. 10: [Power Re-roll] 1. 11: [icon]. 12: Immediately Incarnate! (Once per Clash). Zeal Threshold: 12.",
    "ops": [{"op": "zeal", "onMiss": 2, "onJudicium": 2, "threshold": 12, "benefits": [B(1, "power"), B(2, "evasionReroll"), B(3, "tumble"), B(4, "speed"), B(5, "precision"), B(6, "attackReroll"), B(7, "autoBreak"), B(8, "deadly"), B(10, "powerReroll")]}], "unclear": ["Benefits 9 ('-1 [icon]') and 11 (icon) cannot be read; 12 (Incarnate) is not implemented"]},
   {"name": "The Fire of Zeal", "text": "Start of your turn: Place a Fire [Fire] token in the Knight Pool for every other Knight in Zone 2.", "ops": [{"op": "fireOfZeal", "zone": 2}]}]},
 {"id": "apostate", "name": "Apostate", "tier": "devil", "abilities": [
   {"name": "Uncompromising Believer", "text": "One or more misses: Zeal 3. When you deal a Wound, choose one: Zeal 3 and Reposition 1. / Zeal 2 and gain +2 [Vigor]. / Zeal 1 and lose -3 [Heat]. When another Knight dies, immediately perform a Bonus Attack!",
    "ops": [{"op": "zeal", "onMiss": 3, "benefits": []}, {"op": "woundChoice"}, {"op": "bonusOnKnightDeath"}]},
   {"name": "My Faith is My Rock", "text": "When you are about to die for the first time, during a Clash if you have 6+ Zeal [Zeal] tokens, immediately stand up, move up to 3 spaces and perform a Bonus Attack! If you deal a Wound, you survive. Otherwise, you die.", "ops": [{"op": "dieStand", "need": 6, "survive": True, "firstOnly": True}]}]},
]
def tech(name, unlock, cost, text, depletion, ops, timing, exert, gates=None, gateOps=None, unclear=()):
    return {"name": name, "unlock": unlock, "cost": cost, "text": text, "gates": [{"gate": g, "text": t} for g, t in (gates or [])], "depletion": depletion, "unclear": list(unclear), "ops": ops, "timing": timing, "gateOps": gateOps or {}, "exert": exert}
O = lambda op, **kw: dict(op=op, **kw)
PRc = ex("PowerReroll", "cooldown")
techniques = [
 tech("Persecuted for Righteousness", "Start", [H(2)], "When you deal a Wound, Zeal 1 and gain the Priority Target token. Then, if you have 3+ Zeal [Zeal] tokens on your Knight Board, gain +3 [Vigor].", "discard", [O("persecuted")], "onDealWound", ex("Break", "discard"), [("KING", "This Technique's Depletion becomes [Cooldown].")], {"KING": [O("persecuted", depletion="cooldown")]}),
 tech("Knight Roll", "Start", [H(2)], "[Reaction] Reflex.", "cooldown", [O("reflex", n=1)], "reaction", ex("Opening", "cooldown"), [("KING", "[Reaction] Advanced Reflex."), ("DEVIL", "[Reaction] Superior Reflex.")], {"KING": [O("reflex", n=2)], "DEVIL": [O("reflex", n=3)]}),
 tech("Knight Pose", "Start", [H(2)], "Stand up.", "cooldown", [O("standUp")], "free", PRc, [("KING", "Stand up, then move up to 1 space.")], {"KING": [O("standUp"), O("move", n=1, optional=True)]}),
 tech("Zealous Charge", "Start", [[ACT("combat", "move"), H(1)], [ACT("combat", "move"), Z(1)]], "Rush. If you have 3+ Zeal [Zeal] tokens on your Knight Board, Rush has Auto-fire 1 instead of Auto-break 1.", "cooldown", [O("zealRush", fire=1), O("rush")], "complicated", PRc, [("KING", "Improved Rush. If you have 3+ Zeal [Zeal] tokens on your Knight Board, Rush has Auto-fire 2 instead of Auto-break 1.")], {"KING": [O("zealRush", fire=2), O("improvedRush")]}),
 tech("In Failure, Find Perseverance", "Start", [[Z(1)], [V(1)]], "Full Miss: After clearing the Knight Pool place 1 Opening [Opening] and 1 Break [Break] token in the Knight Pool.", "cooldown", [O("fullMissTokens", tokens={"opening": 1, "break": 1})], "onFullMiss", PRc, [("KING", "2 Closing [Closing] and 2 Fire [Fire] tokens instead.")], {"KING": [O("fullMissTokens", tokens={"closing": 2, "fire": 2})]}),
 tech("Righteous Hand of God", "Investigation 1-2", [], "When you're about to attack, immediately Zeal 1 and gain +X Precision [Precision], where X is the number of Zeal [Zeal] tokens on your Knight Board. You do not benefit from Opening [Opening] tokens during this Attack.", "discard", [O("righteousHand")], "beforeAttack", ex("Break", "discard"), [("DEVIL", "Additionally, if you have 3+ Zeal [Zeal] tokens on your Knight Board, gain +2 [Power].")], {"DEVIL": [O("righteousHand", power=2)]}),
 tech("Evade the Devil's Snare", "Investigation 1-3", [[H(1)], [Z(1)]], "When a Monster adjacent to you is about to perform Signature, place a temporary negative Precision [Precision] token in the Knight Pool.", "cooldown", [O("negPrecision", n=1)], "onSignature", ex("Opening", "cooldown"), [("DRAGON", "2 tokens instead.")], {"DRAGON": [O("negPrecision", n=2)]}, ["Handled as temporary Precision -1 tokens for the Monster (lower the next Evasion Roll difficulty)"]),
 tech("The Fire of my Faith", "Quest: Faithful", [], "When you are about to attack, discard X Knight tokens from the Knight Pool to gain Deadly, where X is the Level of the top card of the BP deck (minimum 1). If fighting against Mobs, X is the Level of the attacked BP card instead. If you discarded a Black [Black] or Hope [Hope] token, immediately Zeal 1.", "cooldown", [O("fireOfFaith")], "beforeAttack", PRc, unclear=["Against Mobs the tokens are discarded once the attacked BP card is chosen"]),
 tech("Armed with Truth", "Investigation 2-2", [H(1)], "When you are about to exhaust (voluntarily or not) a Ranged Weapon [Gear] card, ignore it. Additionally, you may spend a Zeal [Zeal] token to ignore an Exhaust of any Gear [Gear] card instead.", "cooldown", [O("armedWithTruth")], "free", PRc, unclear=["Used as a free action: this turn the next Exhaust (as a cost) of a Ranged Weapon is ignored; with 1 Zeal it applies to any Gear card instead"]),
 tech("Flee From Evil", "Investigation 2-3", [H(2), Z(1)], "If you failed to deal a Wound, immediately move up to 1 space away from the Target.", "cooldown", [O("flee", n=1)], "onNoWound", ex("Opening", "cooldown"), [("DEVIL", "Up to 2 spaces instead."), ("DRAGON", "Up to 3 spaces instead.")], {"DEVIL": [O("flee", n=2)], "DRAGON": [O("flee", n=3)]}, ["'away from the Target' is not enforced"]),
 tech("Theocratic Warfare", "Quest: Truthseeker", [], "-3 [Zeal]: Attack Re-roll 2. OR [Discard] Flip a Mind Condition card.", "instant", [O("theocratic")], "free", None, unclear=["No Exert icon on this card", "Attack Re-roll 2 applies to the next Attack this turn"]),
 tech("Ours is the Hope", "Quest: Truthseeker", [Z(2)], "Defy. OR During the second ability window, gain Hope 1.", "cooldown", [O("oursHope", n=1, defy=1)], "free", PRc, [("DEVIL", "Advanced Defy instead. Hope 2 instead.")], {"DEVIL": [O("oursHope", n=2, defy=2)]}, ["Free action: Hope tokens in the Pool. Defy: offered when Paracelsa is the Target of a Monster Attack (hits reduced like Block)"]),
 tech("Rewarded for my Trials", "Quest: Fireheart Zealot", [], "As a free action, immediately resolve Zeal X depending on your current Peril Level: [MINOR] Zeal 1. [MAJOR] Zeal 2. [GRAVE] Zeal 3. [JUDICIUM] Zeal 4.", "discard", [O("rewarded")], "free", ex("Fire", "discard"), [("DEVIL", "Additionally, gain [Vigor] equal to the number of Zeal [Zeal] tokens you gained.")], {"DEVIL": [O("rewarded", vigor=True)]}),
 tech("Second Chance", "Quest: Fireheart Zealot", [[H(3)], [Z(3)]], "Second Chance. OR If you have 3+ Zeal [Zeal] tokens, ignore the Disemboweled Mortis card.", "cooldown", [O("secondChance")], "onMortisDraw", PRc, [("DRAGON", "Superior Chance.")], {"DRAGON": [O("superiorChance")]}, ["The 'ignore the Disemboweled Mortis card' option is not implemented"]),
 tech("Scion of the Light", "Investigation 3-2", [Z(2)], "Spotlight. OR During the first ability window, spend 2 additional Zeal [Zeal] tokens to add [red Power die] to your Power Pool.", "discard", [O("scion")], "beforeAttack", ex("Opening", "discard"), unclear=[]),
 tech("Shield of Faith", "Investigation 3-3", [[V(3)], [Z(3)]], "Advanced Block.", "cooldown", [O("techBlock", n=2)], "onDefense", PRc),
 tech("Blinding Faith", "Quest: Questioner", [H(2)], "Ignore Attack Responses. Then, during the second ability window, gain Hope 1 and Daze.", "cooldown", [O("ignoreResponses"), O("secondHopeDaze", n=1)], "beforeAttack", PRc, [("DRAGON", "Hope 3 instead.")], {"DRAGON": [O("ignoreResponses"), O("secondHopeDaze", n=3)]}),
 tech("Become a Stumbling Block", "Investigation 4-2", [[V(3)], [Z(2)]], "After you perform a [Judicium draw], Chain Break.", "discard", [O("timed")], "onJudicium", ex("Hope", "discard"), unclear=["Offered after a Judicium draw during a Monster Attack"]),
 tech("Spare Not The Rod", "Investigation 4-3", [V(1)], "When you gain a Crit Chance, gain Zeal 1 and Auto-hope 1.", "instant", [O("spareRod")], "onCritChance", None, unclear=["No Exert icon on this card"]),
 tech("The Just Blade of Kain", "Quest: Inquisitor", [[H(2)], [Z(2)]], "When you are about to attack, gain Spotlight and Heartseeker.", "cooldown", [O("heartseeker"), O("spotlightNow")], "beforeAttack", ex("Closing", "cooldown")),
 tech("Through the Fires of Anatiocha", "Quest: Inquisitor", [Z(4)], "When you are about to die from an Instant Death effect, ignore that death and Displace.", "discard", [O("timed")], "onInstantDeath", ex("Hope", "discard"), unclear=["Instant Death = a death caused directly by a Monster Attack / Response (not by a Judicium or Mortis draw)"]),
 tech("Inquisitor's Pursuit", "Quest: Apostate", [H(1)], "After a Monster performs its movement, immediately move up to 3 spaces toward that Monster. If you have 3+ Zeal [Zeal] tokens, you may move up to your Speed [Speed] value instead.", "cooldown", [O("pursuit", n=3)], "onMonsterMoved", PRc),
 tech("Power of the Pious", "Quest: Apostate", [ACT("combat"), Z(1)], "Perform an Attack with the sword of smiting! Dice: 1. Precision: +2. Power die: [3 red]. Bonus Power: +[2 black]. Reach X. Daze. Gain the following stacking bonuses depending on X: 1+: Break 3. 2+: Deadly. 3+: +[Power Re-roll]. 4+: Attack Re-roll 1. 5+: Hope 2. 6+: +2 [Power].", "discard", [O("piousAttack")], "free", ex("Zeal", "discard"), unclear=["Cost: [Combat action] -X [Zeal] — 1 Zeal is paid as the cost and the rest of X is chosen when used; Hope 2 is placed in the Knight Pool before the Attack"]),
 tech("Nothing Shall Stay My Hand", "Investigation 5-2", [H(2)], "Use this Technique when you are about to perform a Power Roll. Ignore all Responses during this Attack.", "cooldown", [O("ignoreResponses")], "beforePowerRoll", PRc),
 tech("Not Your Time", "Investigation 5-3", [Z(3)], "Bring another Knight back to life and place them adjacent to Paracelsa with 0 [Vigor]. That Knight discards all Condition cards they have.", "discard", [O("notYourTime")], "free", ex("Hope", "discard")),
 tech("Divine Intervention", "Quest: Reverent", [[V(3)], [Z(3)]], "Choose the AI or BP deck. Suppress, then flip the chosen deck face up (the bottom card becomes the top card of its deck). The cards flipped this way remain face up, even when shuffled or removed during Escalation. New cards are added to the deck face down.", "discard", [O("divineIntervention")], "free", ex("Hope", "discard"), unclear=["Only the Suppress is implemented; the face-up deck is not"]),
]
for _t in techniques:
    if _t["name"] == "Rewarded for my Trials": _t["requiresPeril"] = True
data = {"id": "paracelsa", "name": "Paracelsa", "resourceToken": "Zeal",
 "_source": "Knightbook 'A Knight's Tale: Paracelsa' (p.3–4 rules & Knight Setup) + Portrait / Talent / Heroic Arc / Technique sprite sheets (owner-supplied 2026-11-16).",
 "specialRules": {"zeal": "Paracelsa uses special Zeal tokens as a resource. When an effect instructs you to spend a Zeal token, move 1 Zeal token from your Knight Board into the Knight Pool or discard 1 Zeal token from the Knight Pool. Zeal X: During the second ability window, place X Zeal tokens on your Knight Board. Zeal Threshold X: If gaining Zeal tokens would cause you to exceed your Zeal Threshold, gain Zeal tokens up to your Zeal Threshold and place the rest of the tokens in the Knight Pool. Falsity: During the Attack Roll step, you may re-roll your Crit die without gaining [Heat]. If you re-roll a Crit die that's already a hit, immediately gain 1 Zeal token."},
 "setup": {"virtues": {"Bravery": 1, "Insight": 1, "Tenacity": 2}, "rapportBoon": {"text": "Crit Chance: Auto-break 1.", "note": "Rogue's Path에서 미적용."}, "explorationCipher": "**07", "portraits": ["Quester"], "portrait": "quester", "talent": "Quester", "heroicArc": "Quester", "perilArc": "Quester",
   "techniques": ["Knight Pose", "Knight Roll", "Persecuted for Righteousness", "Zealous Charge", "In Failure, Find Perseverance"], "gear": ["Knighves", "Militia Morgenstern"],
   "backSides": "Knightbook lists the starting cards as 'Knight Pose // Knight Prowess, Knight Roll // Blessed Insight, Persecuted for Righteousness // Through Heaven's Eyes, Zealous Charge // Sustain me Through my Trials, In Failure, Find Perseverance // I Shall Fear No Evil' — the back sides are not in the supplied sheets."},
 "firstDeath": {"text": "Paracelsa's First Death Special Event: Mark the First Death box on your Knight Sheet. Gain +1 Sigh of the Graal.", "ops": [{"op": "markFirstDeath"}, {"op": "gainSigh", "n": 1}], "note": "[해석, 확인 필요] Fleischritter와 같은 보상으로 처리."},
 "components": {"portraits": 2, "talents": 3, "heroicArcs": 4, "perilArcs": 4, "techniques": 26, "gear": 5, "zealTokens": 6},
 "talents": talents, "heroicArcs": arcs, "perilArcsRef": "data/knights/peril_arcs.json → arcs.paracelsa", "techniques": techniques, "missing": [],
 "portraits": [
  {"id": "quester", "name": "Quester", "tier": "starting", "classes": ["Quester"], "powerDie": "red", "cardRefresh": 1, "heatRefresh": 2, "handLimit": 4, "speed": 4, "baneLimit": 4},
  {"id": "truthseeker-fireheart", "name": "Truthseeker / Fireheart Zealot", "tier": "vassal", "classes": ["Truthseeker", "Fireheart Zealot"], "powerDie": "red", "cardRefresh": 1, "heatRefresh": 3, "handLimit": 5, "speed": 4, "baneLimit": 5},
  {"id": "inquisitor-apostate", "name": "Inquisitor / Apostate", "tier": "devil", "classes": ["Inquisitor", "Apostate"], "powerDie": "red", "powerDice": 2, "cardRefresh": 2, "heatRefresh": 4, "handLimit": 6, "speed": 5, "baneLimit": 6}]}
out = os.path.join(os.path.dirname(__file__), '..', 'data', 'knights', 'paracelsa.json'); json.dump(data, open(out, 'w'), ensure_ascii=False, indent=1); print('wrote paracelsa.json', len(techniques), len(arcs))
